pub(super) fn catalog(locale: &str) -> &'static PersonNames {
    match locale {
        "ar_SA" => &AR_SA,
        "de_DE" => &DE_DE,
        "fa_IR" => &FA_IR,
        "fr_FR" => &FR_FR,
        "it_IT" => &IT_IT,
        "ja_JP" => &JA_JP,
        "nl_NL" => &NL_NL,
        "pt_BR" => &PT_BR,
        "pt_PT" => &PT_PT,
        "tr_TR" => &TR_TR,
        "zh_CN" => &ZH_CN,
        "zh_TW" => &ZH_TW,
        _ => &EN_US,
    }
}

